import { total } from './cart.js';

// The printed wholesale price list gives 5% off from this many lines. It is kept
// here, apart from the cart's own threshold, so that changing the cart's bulk
// rule does not change what wholesale customers are invoiced.
const PRICE_LIST_BULK_MIN_LINES = 10;

// Invoices for wholesale orders (#7). The amount due follows the printed price
// list that wholesale customers order from: list price below 10 lines, 5% off
// from 10 lines, half a yen rounded up. No customer discount.
export function invoice(customer, items) {
  return { customer, due: total(items, 0, PRICE_LIST_BULK_MIN_LINES) };
}

