import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }]), 200);
});

test('a cart of 2 lines gets the 5% bulk discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 238); // 250 * 0.95 = 237.5
});

test('a cart of 2 lines: customer discount, then the bulk discount once', () => {
  assert.equal(total([{ price: 600, qty: 1 }, { price: 400, qty: 1 }], 0.1), 855); // 1,000 -> 900 -> 5% off
});

// #12: the customer's discount is applied once.
test('customer discount is applied once: 10% off 1,000 is 900', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount applies once, after the customer discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10,000 -> 9,000 -> 5% off
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

